 $post=$posts->save(['id'=>'00000000-0000-4000-8000-000000000001','slug'=>'bai-viet','title'=>'Bài nguồn','excerpt'=>'Tóm tắt','contentHtml'=>'<p>Nội dung nguồn.</p>','category'=>'Cẩm nang','author'=>'JinMemo','status'=>'DRAFT','version'=>0],'admin');$en=['title'=>'English story','slug'=>'english-story','excerpt'=>'English excerpt','contentHtml'=>'<script>alert(1)</script><p>English story.</p>','seoTitle'=>'','seoDescription'=>''];$r=['kind'=>'POST','id'=>$post['id'],'version'=>$post['version'],'publish'=>true,'english'=>$en];trStatus(400,fn()=>$translations->save(array_replace($r,['english'=>array_replace($en,['contentHtml'=>'<script>bad()</script>'])]),'admin'));$post=$translations->save($r,'admin');trCheck($post['english']['category']==='Travel guide'&&!str_contains($post['english']['contentHtml'],'script'),'Shared category/sanitize');trStatus(404,fn()=>$posts->find('english-story','en'));trCheck($posts->revisions($post['id'])[0]['reason']==='TRANSLATE','Translation history');
