 $rows=$translations->list();trCheck(count($rows)===3&&count(array_filter($rows,fn($i)=>$i['status']==='NEEDS_REVIEW'))===2,'Translation overview');trStatus(400,fn()=>$translations->save(array_merge($r,['extra'=>true]),'admin'));
